val v1 = HttpRoutes.of[IO] {
  case req @ POST -> Root / "v1" / "orders" =>
    for {
      body <- req.as[OrderRequest]                 // circe decoder = published shape
      ack  <- orders.submit(body.toDomain())       // domain types stay codec-free
      resp <- Ok(ack.toDto)
    } yield resp
}
